const body = $input.item.json.body ?? $input.item.json;

const event = (body.event || '').toLowerCase();
const instance = body.instance || body.instanceName || '';

// Só nos interessa evento de mensagem nova/atualizada
if (!event.includes('messages.upsert')) {
  return [{ json: { valido: false, motivo: 'evento ignorado: ' + event } }];
}

const data = body.data || {};
const key = data.key || {};
const message = data.message || {};

const remoteJid = key.remoteJid || '';

// Ignora grupos e status broadcast (só monitoramos conversas 1:1)
if (remoteJid.endsWith('@g.us') || remoteJid === 'status@broadcast' || !remoteJid) {
  return [{ json: { valido: false, motivo: 'grupo, status ou remoteJid ausente' } }];
}

const contato = remoteJid.split('@')[0];

const conteudo =
  message.conversation ||
  (message.extendedTextMessage && message.extendedTextMessage.text) ||
  (message.imageMessage && message.imageMessage.caption) ||
  (message.videoMessage && message.videoMessage.caption) ||
  (message.documentMessage && message.documentMessage.caption) ||
  (message.audioMessage ? '[áudio]' : null) ||
  (message.stickerMessage ? '[figurinha]' : null) ||
  null;

if (!conteudo) {
  return [{ json: { valido: false, motivo: 'mensagem sem texto/mídia relevante' } }];
}

const tipoMensagem =
  message.conversation || message.extendedTextMessage
    ? 'texto'
    : message.imageMessage
    ? 'imagem'
    : message.videoMessage
    ? 'video'
    : message.audioMessage
    ? 'audio'
    : message.documentMessage
    ? 'documento'
    : message.stickerMessage
    ? 'figurinha'
    : 'outro';

const timestampSeconds = Number(data.messageTimestamp) || Math.floor(Date.now() / 1000);

return [
  {
    json: {
      valido: true,
      instancia: instance,
      contato,
      contato_nome: data.pushName || null,
      direcao: key.fromMe ? 'enviada' : 'recebida',
      conteudo,
      tipo_mensagem: tipoMensagem,
      message_id: key.id || null,
      timestamp: new Date(timestampSeconds * 1000).toISOString(),
    },
  },
];
